pub const MMAP = struct {
    file: fs.File,
    buffer: []align(mem.page_size) u8,
    allocator: Allocator,

    pub fn open(allocator: Allocator, path: []const u8, mode: fs.File.OpenFlags) !MMAP {
        const file = try fs.cwd().openFile(path, mode);
        errdefer file.close();
        const stat = try file.stat();
        var size = stat.size;
        const is_writable = mode.mode == .read_write or mode.mode == .write_only;
        const prot_flags = if (is_writable)
            std.posix.PROT.READ | std.posix.PROT.WRITE
        else
            std.posix.PROT.READ;
        if (size == 0) {
            if (is_writable) {
                const page_size = mem.page_size;
                try file.setEndPos(page_size);
                size = page_size;
            } else {
                return error.FileIsEmpty;
            }
        }
        const map_type = if (is_writable) .SHARED else .PRIVATE;
        const buffer = try std.posix.mmap(
            null,
            size,
            prot_flags,
            .{ .TYPE = map_type },
            file.handle,
            0,
        );
        return .{ .file = file, .buffer = buffer, .allocator = allocator };
    }

    pub fn close(self: *MMAP) void {
        std.posix.munmap(self.buffer);
        self.file.close();
    }

    pub fn read(self: *const MMAP, offset: usize, len: usize) []const u8 {
        return self.buffer[offset..math.min(offset + len, self.buffer.len)];
    }

    pub fn write(self: *MMAP, offset: usize, data: []const u8) !void {
        if (offset + data.len > self.buffer.len) return error.OutOfBounds;
        @memcpy(self.buffer[offset .. offset + data.len], data);
        try std.posix.msync(self.buffer, .{ .SYNC = true });
    }

    pub fn append(self: *MMAP, data: []const u8) !void {
        const old_size = self.buffer.len;
        const new_size = old_size + data.len;
        std.posix.munmap(self.buffer);
        try self.file.setEndPos(new_size);
        try self.file.pwriteAll(data, old_size);
        self.buffer = try std.posix.mmap(
            null,
            new_size,
            std.posix.PROT.READ | std.posix.PROT.WRITE,
            .{ .TYPE = .SHARED },
            self.file.handle,
            0,
        );
    }
};

pub const DurableWriter = struct {
    file: fs.File,
    buffer: [4096]u8,
    pos: usize = 0,
    allocator: Allocator,

    pub fn init(allocator: Allocator, path: []const u8) !DurableWriter {
        const file = try fs.cwd().createFile(path, .{});
        return .{
            .file = file,
            .allocator = allocator,
            .buffer = mem.zeroes([4096]u8),
        };
    }

    pub fn deinit(self: *DurableWriter) void {
        self.flush() catch {};
        self.file.close();
    }

    pub fn write(self: *DurableWriter, data: []const u8) !void {
        var remaining = data;
        while (remaining.len > 0) {
            const chunk = math.min(remaining.len, self.buffer.len - self.pos);
            @memcpy(self.buffer[self.pos .. self.pos + chunk], remaining[0..chunk]);
            self.pos += chunk;
            remaining = remaining[chunk..];
            if (self.pos == self.buffer.len) {
                try self.flush();
            }
        }
    }

    pub fn flush(self: *DurableWriter) !void {
        if (self.pos > 0) {
            try self.file.writeAll(self.buffer[0..self.pos]);
            self.pos = 0;
        }
    }

    pub fn writeAll(self: *DurableWriter, data: []const u8) !void {
        try self.write(data);
        try self.flush();
    }
};

pub const BufferedReader = struct {
    file: fs.File,
    buffer: [4096]u8,
    pos: usize = 0,
    limit: usize = 0,
    allocator: Allocator,

    pub fn init(allocator: Allocator, path: []const u8) !BufferedReader {
        const file = try fs.cwd().openFile(path, .{});
        return .{ .file = file, .allocator = allocator, .buffer = undefined };
    }

    pub fn deinit(self: *BufferedReader) void {
        self.file.close();
    }

    pub fn read(self: *BufferedReader, buf: []u8) !usize {
        var total: usize = 0;
        while (total < buf.len) {
            if (self.pos < self.limit) {
                const avail = math.min(self.limit - self.pos, buf.len - total);
                @memcpy(buf[total .. total + avail], self.buffer[self.pos .. self.pos + avail]);
                self.pos += avail;
                total += avail;
            } else {
                self.limit = try self.file.read(self.buffer[0..]);
                self.pos = 0;
                if (self.limit == 0) break;
            }
        }
        return total;
    }

    pub fn readUntil(self: *BufferedReader, delim: u8, allocator: Allocator) ![]u8 {
        var list = std.ArrayList(u8).init(allocator);
        errdefer list.deinit();
        while (true) {
            if (self.pos < self.limit) {
                const chunk = self.buffer[self.pos..self.limit];
                for (chunk, 0..) |c, i| {
                    try list.append(c);
                    if (c == delim) {
                        self.pos += i + 1;
                        return list.toOwnedSlice();
                    }
                }
                self.pos = self.limit;
            } else {
                self.limit = try self.file.read(self.buffer[0..]);
                self.pos = 0;
                if (self.limit == 0) return list.toOwnedSlice();
            }
        }
    }

    pub fn peek(self: *const BufferedReader) ?u8 {
        if (self.pos < self.limit) return self.buffer[self.pos];
        return null;
    }
};

pub const BufferedWriter = struct {
    file: fs.File,
    buffer: []u8,
    pos: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, file: fs.File, buffer_size: usize) !BufferedWriter {
        const buffer = try allocator.alloc(u8, buffer_size);
        return .{
            .file = file,
            .buffer = buffer,
            .pos = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *BufferedWriter) void {
        self.allocator.free(self.buffer);
    }

    pub fn writeByte(self: *BufferedWriter, byte: u8) !void {
        if (self.pos >= self.buffer.len) {
            try self.flush();
        }
        self.buffer[self.pos] = byte;
        self.pos += 1;
    }

    pub fn writeBytes(self: *BufferedWriter, data: []const u8) !void {
        var written: usize = 0;
        while (written < data.len) {
            const available = self.buffer.len - self.pos;
            const to_write = @min(available, data.len - written);
            @memcpy(self.buffer[self.pos .. self.pos + to_write], data[written .. written + to_write]);
            self.pos += to_write;
            written += to_write;
            if (self.pos >= self.buffer.len) {
                try self.flush();
            }
        }
    }

    pub fn flush(self: *BufferedWriter) !void {
        if (self.pos > 0) {
            try self.file.writeAll(self.buffer[0..self.pos]);
            self.pos = 0;
        }
    }
