pub fn pathJoin(allocator: Allocator, parts: []const []const u8) ![]u8 {
    var total_len: usize = 0;
    for (parts) |part| total_len += part.len + 1;
    if (total_len > 0) total_len -= 1;
    const path = try allocator.alloc(u8, total_len);
    var pos: usize = 0;
    for (parts, 0..) |part, i| {
        @memcpy(path[pos .. pos + part.len], part);
        pos += part.len;
        if (i < parts.len - 1) {
            path[pos] = '/';
            pos += 1;
