pub fn toLittleEndian(comptime T: type, value: T) T {
    return switch (@import("builtin").target.cpu.arch.endian()) {
        .little => value,
        .big => @byteSwap(value),
    };
}

pub fn fromLittleEndian(comptime T: type, bytes: *const [@sizeOf(T)]u8) T {
    return switch (@import("builtin").target.cpu.arch.endian()) {
        .little => mem.readInt(T, bytes, .little),
        .big => @byteSwap(mem.readInt(T, bytes, .little)),
    };
}

pub fn toBigEndian(comptime T: type, value: T) T {
    return switch (@import("builtin").target.cpu.arch.endian()) {
        .little => @byteSwap(value),
        .big => value,
    };
}

pub fn fromBigEndian(comptime T: type, bytes: *const [@sizeOf(T)]u8) T {
    return switch (@import("builtin").target.cpu.arch.endian()) {
        .little => @byteSwap(mem.readInt(T, bytes, .big)),
        .big => mem.readInt(T, bytes, .big),
    };
}

pub fn readBinary(comptime T: type, path: []const u8, allocator: Allocator) ![]T {
    const data = try readFile(allocator, path);
    defer allocator.free(data);
    const count = data.len / @sizeOf(T);
    const result = try allocator.alloc(T, count);
    @memcpy(mem.sliceAsBytes(result), data);
    return result;
}

pub fn writeBinary(comptime T: type, path: []const u8, data: []const T) !void {
    const bytes = mem.sliceAsBytes(data);
    try writeFile(path, bytes);
}

pub fn readInt(comptime T: type, reader: anytype) !T {
    var bytes: [@sizeOf(T)]u8 = undefined;
    try reader.readNoEof(&bytes);
    return mem.readInt(T, &bytes, .little);
}

pub fn writeInt(comptime T: type, writer: anytype, value: T) !void {
    var bytes: [@sizeOf(T)]u8 = undefined;
    mem.writeInt(T, &bytes, value, .little);
    try writer.writeAll(&bytes);
}

pub fn readFloat(reader: anytype) !f32 {
    var bytes: [4]u8 = undefined;
    try reader.readNoEof(&bytes);
    return @bitCast(mem.readInt(u32, &bytes, .little));
}

pub fn writeFloat(writer: anytype, value: f32) !void {
    var bytes: [4]u8 = undefined;
    mem.writeInt(u32, &bytes, @bitCast(value), .little);
    try writer.writeAll(&bytes);
}

pub fn EndianSafeWriter(comptime WriterType: type) type {
    return struct {
        writer: WriterType,

        pub fn writeInt(self: *@This(), comptime T: type, value: T) !void {
            var bytes: [@sizeOf(T)]u8 = undefined;
            mem.writeInt(T, &bytes, value, .big);
            try self.writer.writeAll(&bytes);
        }

        pub fn writeFloat(self: *@This(), value: f32) !void {
            var bytes: [4]u8 = undefined;
            mem.writeInt(u32, &bytes, @bitCast(value), .big);
            try self.writer.writeAll(&bytes);
        }
    };
}

pub fn EndianSafeReader(comptime ReaderType: type) type {
    return struct {
        reader: ReaderType,

        pub fn readInt(self: *@This(), comptime T: type) !T {
            var bytes: [@sizeOf(T)]u8 = undefined;
            try self.reader.readNoEof(&bytes);
            return mem.readInt(T, &bytes, .big);
        }

        pub fn readFloat(self: *@This()) !f32 {
            var bytes: [4]u8 = undefined;
            try self.reader.readNoEof(&bytes);
            return @bitCast(mem.readInt(u32, &bytes, .big));
        }
    };
}

pub fn computeChecksum(path: []const u8, allocator: Allocator) !u64 {
    const data = try readFile(allocator, path);
    defer allocator.free(data);
    const key_bytes: [16]u8 = @bitCast(@as(u128, 0));
    var hasher = crypto.hash.Siphash64(1, 3).init(&key_bytes);
    hasher.update(data);
    return hasher.final();
}

pub fn hashBytes(data: []const u8) u64 {
    return hash64(data);
}

pub fn hashString(str: []const u8) u64 {
