}

fn randomHex(allocator: Allocator, nbytes: usize) ![]u8 {
    var prng = std.rand.DefaultPrng.init(@bitCast(std.time.nanoTimestamp()));
    const r = prng.random();
    var buf = try allocator.alloc(u8, nbytes);
    r.bytes(buf);
    defer allocator.free(buf);
    var out = try std.fmt.allocPrint(allocator, "{s}", .{std.fmt.fmtSliceHexLower(buf)});
    return out;
}

pub fn generateTempPath(allocator: Allocator, prefix: []const u8) ![]u8 {
    const hex = try randomHex(allocator, 16);
    defer allocator.free(hex);
    return try std.fmt.allocPrint(allocator, "/tmp/{s}{s}", .{ prefix, hex });
}

pub fn atomicWrite(allocator: Allocator, path: []const u8, data: []const u8) !void {
    const hex = try randomHex(allocator, 8);
    defer allocator.free(hex);
    const tmp = try std.fmt.allocPrint(allocator, "{s}.tmp.{s}", .{ path, hex });
    defer allocator.free(tmp);
    {
        const f = try fs.cwd().createFile(tmp, .{});
        defer f.close();
        try f.writeAll(data);
        try f.sync();
    }
    try fs.cwd().rename(tmp, path);
}

pub fn streamLines(reader: anytype, allocator: Allocator, visitor: anytype) !void {
    var buf = std.ArrayList(u8).init(allocator);
    defer buf.deinit();
    var one: [1]u8 = undefined;
    while (true) {
        const n = try reader.read(&one);
        if (n == 0) break;
        if (one[0] == '\n') {
            try visitor(buf.items);
            buf.clearRetainingCapacity();
        } else {
            try buf.append(one[0]);
        }
    }
    if (buf.items.len > 0) try visitor(buf.items);
}

pub fn mmapFile(path: []const u8) ![]align(mem.page_size) u8 {
    const file = try fs.cwd().openFile(path, .{});
    defer file.close();
    const file_size = try file.getEndPos();
    if (file_size == 0) {
        return error.FileIsEmpty;
    }
    const mapped = try std.posix.mmap(
        null,
        file_size,
        std.posix.PROT.READ,
        .{ .TYPE = .PRIVATE },
        file.handle,
        0,
    );
    return @alignCast(mapped);
}

pub fn mmapFileWritable(path: []const u8) ![]align(mem.page_size) u8 {
    const file = try fs.cwd().openFile(path, .{ .mode = .read_write });
    defer file.close();
    var file_size = try file.getEndPos();
    if (file_size == 0) {
        const page_size = mem.page_size;
        try file.setEndPos(page_size);
        file_size = page_size;
    }
    const mapped = try std.posix.mmap(
        null,
        file_size,
        std.posix.PROT.READ | std.posix.PROT.WRITE,
        .{ .TYPE = .SHARED },
        file.handle,
        0,
    );
    return @alignCast(mapped);
}

pub fn munmapFile(mapping: []align(mem.page_size) const u8) void {
    std.posix.munmap(mapping);
}

